package com.example.discussions;import com.example.discussions.exception.ApiException;import com.example.discussions.model.User;import com.example.discussions.repository.UserRepository;import com.example.discussions.service.CurrentUser;import org.junit.jupiter.api.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;class AuthorizationTest{@AfterEach void clear(){SecurityContextHolder.clearContext();}@Test void rejectsEditingAnotherUsersContent(){var repo=mock(UserRepository.class);var me=new User();me.id=1L;me.username="me";var author=new User();author.id=2L;SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken("me","",java.util.List.of()));when(repo.findByUsernameIgnoreCase("me")).thenReturn(Optional.of(me));assertThrows(ApiException.class,()->new CurrentUser(repo).ownerOrAdmin(author));}@Test void administratorMayEdit(){var repo=mock(UserRepository.class);var admin=new User();admin.id=1L;admin.username="admin";admin.role=User.Role.ADMIN;var author=new User();author.id=2L;SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken("admin","",java.util.List.of()));when(repo.findByUsernameIgnoreCase("admin")).thenReturn(Optional.of(admin));assertDoesNotThrow(()->new CurrentUser(repo).ownerOrAdmin(author));}}
